## 9. Testing

### 9.1 Unit Test (Jest + RTL)

```tsx
// src/components/ui/__tests__/ProductCard.test.tsx
import { render, screen } from '@testing-library/react';
import { BrowserRouter } from 'react-router-dom';
import { ProductCard } from '../ProductCard';
import { Product } from '../../types';

const mockProduct: Product = {
  id: 1,
  title: 'Test Shirt',
  price: 29.99,
  image: '/images/test-shirt.jpg',
};

test('renders product card with title and price', () => {
  render(
    <BrowserRouter>
      <ProductCard product={mockProduct} />
    </BrowserRouter>
  );

  expect(screen.getByText(/Test Shirt/i)).toBeInTheDocument();
  expect(screen.getByText(/\$29\.99/i)).toBeInTheDocument();
});
```

### 9.2 Integration Test (API mock)

```tsx
// src/components/pages/__tests__/ProductList.test.tsx
import { render, screen, waitFor } from '@testing-library/react';
import { rest } from 'msw';
import { setupServer } from 'msw/node';
import { ProductList } from '../ProductList';
import { BrowserRouter } from 'react-router-dom';

const server = setupServer(
  rest.get(`${import.meta.env.VITE_API_URL}/products`, (_, res, ctx) => {
    return res(
      ctx.json([
        { id: 1, title: 'Mock Shirt', price: 19.99, image: '/mock.jpg' },
      ])
    );
  })
);

beforeAll(() => server.listen());
afterEach(() => server.resetHandlers());
afterAll(() => server.close());

test('displays products from API', async () => {
  render(
    <BrowserRouter>
      <ProductList />
    </BrowserRouter>
  );

  await waitFor(() => screen.getByText(/Mock Shirt/i));
  expect(screen.getByText(/\$19\.99/i)).toBeInTheDocument();
});
```

---

## 10. Performance & SEO

| Technique | How |
|-----------|-----|
| **Code splitting** | Vite automatically splits per route. |
| **Lazy load images** | `loading="lazy"` attribute or `react-lazyload`. |
| **SSR / SSG** | Use **Next.js** if you need SEO‑heavy pages; otherwise, pre‑render critical pages with Vite + `vite-plugin-ssg`. |
| **Structured data** | Add JSON‑LD in `<head>` for products. |
| **Cache API responses** | Service worker or SWR caching. |
| **Bundle size** | `npm run build --report` to inspect. |

---

## 11. Deployment

### 11.1 Vercel

1. Push repo to GitHub.  
2. Import project in Vercel → set environment variable `VITE_API_URL` to your backend URL.  
3. Vercel auto‑detects Vite → builds & deploys.  
4. Preview URLs for every PR.

### 11.2 Docker (Optional)

```dockerfile
# Dockerfile
FROM node:20-alpine AS builder
WORKDIR /app
COPY package*.json ./
RUN npm ci
COPY . .
RUN npm run build

FROM nginx:alpine
COPY --from=builder /app/dist /usr/share/nginx/html
EXPOSE 80
CMD ["nginx", "-g", "daemon off;"]
```

```bash
docker build -t ecommerce-frontend .
docker run -p 80:80 ecommerce-frontend
```

---

## 12. CI/CD (GitHub Actions)

```yaml
# .github/workflows/ci.yml
name: CI

on:
  push:
    branches: [main]
  pull_request:

jobs:
  build-test:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-node@v4
        with:
          node-version: 20
      - run: npm ci
      - run: npm run lint
      - run: npm run test
      - run: npm run build
```

---

## 13. Security Checklist

| Item | Action |
|------|--------|
| **HTTPS** | Vercel provides SSL automatically. |
| **CORS** | Backend must allow your frontend domain. |
| **XSS** | Escape all user‑generated content; use `dangerouslySetInnerHTML` sparingly. |
| **CSRF** | Use SameSite cookies or CSRF tokens. |
| **Auth** | Store JWT in `httpOnly` cookie or `localStorage` (with caution). |
| **Rate limiting** | Backend side. |

---

## 14. Quick Start Script

```bash
# Create project
npm create vite@latest ecommerce-frontend -- --template react-ts
cd ecommerce-frontend

# Install deps
npm i tailwindcss postcss autoprefixer
npx tailwindcss init -p
npm i @reduxjs/toolkit react-redux axios react-router-dom @testing-library/react @testing-library/jest-dom jest msw

# Add Tailwind config
# (tailwind.config.js)
module.exports = {
  content: ['./index.html', './src/**/*.{js,ts,jsx,tsx}'],
  theme: { extend: {} },
  plugins: [],
};

# Add scripts to package.json
{
  "scripts": {
    "dev": "vite",
    "build": "vite build",
    "preview": "vite preview",
    "lint": "eslint . --ext .ts,.tsx",
    "test": "jest"
  }
}

# Run dev
npm run dev
```

